"""Parse BOQ files (Excel .xlsx and JSON) into structured line items."""

import json
from decimal import ROUND_HALF_UP, Decimal
from io import BytesIO
from typing import Any

from openpyxl import load_workbook

REQUIRED_COLUMNS = {"description", "quantity", "unit", "rate"}
OPTIONAL_COLUMNS = {"category", "specification"}


def _clean_value(value: Any) -> str:
    if value is None:
        return ""
    return str(value).strip()


def _to_decimal(value: Any) -> Decimal:
    if value is None:
        return Decimal("0")
    try:
        return Decimal(str(value)).quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)
    except Exception:
        return Decimal("0")


def parse_excel(file_bytes: bytes) -> list[dict[str, Any]]:
    """Parse an Excel .xlsx file into BOQ line items."""
    wb = load_workbook(filename=BytesIO(file_bytes), data_only=True)
    ws = wb.active
    if ws is None:
        raise ValueError("Excel file has no active worksheet")

    # Find header row
    header_row = None
    headers: dict[str, int] = {}
    for row_idx, row in enumerate(ws.iter_rows(values_only=True), start=1):
        if not row:
            continue
        row_strs = [str(c).strip().lower() if c is not None else "" for c in row]
        found = {h for h in row_strs if h in REQUIRED_COLUMNS or h in OPTIONAL_COLUMNS}
        if REQUIRED_COLUMNS.issubset(found):
            header_row = row_idx
            for col_idx, cell in enumerate(row, start=1):
                if cell is not None:
                    key = str(cell).strip().lower()
                    if key in REQUIRED_COLUMNS or key in OPTIONAL_COLUMNS:
                        headers[key] = col_idx
            break

    if header_row is None:
        raise ValueError(f"Could not find header row with required columns: {REQUIRED_COLUMNS}")

    items = []
    for row in ws.iter_rows(min_row=header_row + 1, values_only=True):
        if not row or all(cell is None or str(cell).strip() == "" for cell in row):
            continue

        description = _clean_value(row[headers.get("description", 1) - 1])
        if not description:
            continue

        quantity = _to_decimal(row[headers.get("quantity", 1) - 1])
        rate = _to_decimal(row[headers.get("rate", 1) - 1])
        amount = (quantity * rate).quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)

        items.append({
            "line_number": len(items) + 1,
            "category": _clean_value(row[headers.get("category", 1) - 1]) if "category" in headers else None,
            "description": description,
            "specification": _clean_value(row[headers.get("specification", 1) - 1]) if "specification" in headers else None,
            "unit": _clean_value(row[headers.get("unit", 1) - 1]) or "nos",
            "quantity": quantity,
            "rate": rate,
            "amount": amount,
        })

    return items


def parse_json(file_bytes: bytes) -> list[dict[str, Any]]:
    """Parse a JSON BOQ file into line items."""
    data = json.loads(file_bytes.decode("utf-8"))
    if not isinstance(data, list):
        raise ValueError("JSON BOQ must be an array of objects")

    items = []
    for i, row in enumerate(data, start=1):
        if not isinstance(row, dict):
            continue
        desc = _clean_value(row.get("description", ""))
        if not desc:
            continue

        quantity = _to_decimal(row.get("quantity"))
        rate = _to_decimal(row.get("rate"))
        amount = (quantity * rate).quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)

        items.append({
            "line_number": i,
            "category": _clean_value(row.get("category")) or None,
            "description": desc,
            "specification": _clean_value(row.get("specification")) or None,
            "unit": _clean_value(row.get("unit")) or "nos",
            "quantity": quantity,
            "rate": rate,
            "amount": amount,
        })

    return items

